import numpy as np
import pandas as pd
import hashlib

def make_F(n: int, m: int, seed: int = 12345):
    F = np.empty((n, m))
    s = seed
    for i in range(n):
        for j in range(m):
            s = (s * 1103515245 + 12345) % 2147483648
            F[i, j] = float(s % 20001 - 10000) * 0.000123 * float(j + 1)
    return F

def make_y(n: int):
    return np.array([(i * 7 % 5) % 2 for i in range(n)])

def _r(x) -> str:
    if isinstance(x, pd.Scalar):
        return repr(x.f) if x.kind == 0 else (repr(x.s) if x.kind == 3 else str(x))
    elif isinstance(x, float) or isinstance(x, str):
        return repr(x)
    else:
        return str(x)

@test
def test_rolling():
    F = make_F(40, 8)
    y = make_y(40)
    df = pd.DataFrame(F, columns=[f"ch{i}" for i in range(F.shape[1])])
    df["label"] = y
    g = df.groupby("label").mean()
    d = df.drop(columns="label").describe()
    c = df.drop(columns="label").corr()
    csv = df.to_csv(float_format="%.17g")

    F2 = make_F(13, 4, seed=777)
    F2[3, 1] = float("nan")
    F2[7, 2] = float("nan")
    d2 = pd.DataFrame(F2, columns=["a", "b", "c", "d"])
